function createdAudioQuery(state, folderId, now) {
  if (
    typeof folderId !== "string" ||
    !/^[A-Za-z0-9_-]{5,150}$/.test(folderId) ||
    folderId.startsWith("YOUR_")
  )
    throw Error("Set the Google Drive folder ID.");
  if (!Number.isSafeInteger(now)) throw Error("Drive schedule time is unavailable.");
  if (!state.activeAt) {
    state.activeAt = now;
    state.cursor = now;
    return null;
  }
  if (!Number.isSafeInteger(state.cursor) || state.cursor < state.activeAt || state.cursor >= now)
    return null;
  const boundary = new Date(now).toISOString();
  const after = new Date(Math.max(state.activeAt, state.cursor - 120000)).toISOString();
  const q =
    "'" +
    folderId +
    "' in parents and trashed = false and createdTime > '" +
    after +
    "' and createdTime <= '" +
    boundary +
    "'";
  return { folderId, until: now, q };
}

function normalizeNotionParent(value) {
  if (typeof value !== "string") throw Error("Set the Notion parent page ID.");
  const id = value.replace(/-/g, "").toLowerCase();
  if (!/^[0-9a-f]{32}$/.test(id)) throw Error("Set the Notion parent page ID.");
  return [id.slice(0, 8), id.slice(8, 12), id.slice(12, 16), id.slice(16, 20), id.slice(20)].join(
    "-",
  );
}

const settings = { folder: "YOUR_DRIVE_FOLDER_ID", parent: "YOUR_NOTION_PAGE_ID" };
const parentId = normalizeNotionParent(settings.parent);
const state = $getWorkflowStaticData("global");
const now = Date.parse($input.first().json.timestamp);
const poll = createdAudioQuery(state, settings.folder, now);
return poll ? [{ json: { ...poll, parentId } }] : [];

function audioSpec(mime, name) {
  const types = {
    "audio/mpeg": ["mp3", "mpeg", "mpga"],
    "audio/mp3": ["mp3"],
    "audio/mp4": ["m4a", "mp4"],
    "audio/x-m4a": ["m4a"],
    "audio/m4a": ["m4a"],
    "audio/flac": ["flac"],
    "audio/x-flac": ["flac"],
    "audio/ogg": ["ogg"],
    "application/ogg": ["ogg"],
    "audio/wav": ["wav"],
    "audio/x-wav": ["wav"],
    "audio/vnd.wave": ["wav"],
    "audio/webm": ["webm"],
  };
  const extensions = types[mime];
  if (!extensions) return null;
  const suffix = String(name ?? "")
    .split(".")
    .at(-1)
    .toLowerCase();
  return extensions.includes(suffix) ? suffix : extensions[0];
}

function driveAudioEvents(items, folderId, fromTrigger, spec) {
  if (
    typeof folderId !== "string" ||
    !/^[A-Za-z0-9_-]{5,150}$/.test(folderId) ||
    folderId.startsWith("YOUR_")
  )
    throw Error("Set the Google Drive folder ID.");
  if (!Array.isArray(items)) throw Error("Expected a list of Drive files.");
  const found = new Map();
  for (const item of items) {
    if (fromTrigger && (item?.eventType !== "file_created" || item.itemType !== "file")) continue;
    if (
      !item?.parents?.includes(folderId) ||
      item.trashed === true ||
      !spec(item.mimeType, item.name)
    )
      continue;
    const id = fromTrigger ? item.fileId : item.id;
    if (typeof id !== "string" || !/^[A-Za-z0-9_-]{5,150}$/.test(id))
      throw Error("Google Drive did not provide a valid audio file ID.");
    if (!found.has(id)) found.set(id, { id, folderId, mime: item.mimeType, name: item.name });
  }
  return [...found.values()];
}

const poll = $("Set the Drive folder and Notion parent").first().json;
const pages = $input.all().map((item) => item.json.body);
if (
  !pages.length ||
  pages.at(-1)?.nextPageToken ||
  pages.some((p) => !Array.isArray(p?.files) || p.incompleteSearch === true)
)
  throw Error("The Drive folder listing was incomplete. No recordings were dispatched.");
const files = driveAudioEvents(
  pages.flatMap((p) => p.files),
  poll.folderId,
  false,
  audioSpec,
);
return files.length
  ? files.map((file) => ({
      json: { file, parentId: poll.parentId, key: "notion:" + poll.parentId + ":" + file.id },
    }))
  : [{ json: { file: null, parentId: poll.parentId, key: "no-audio" } }];

const item = $("Process one recording at a time").all(1, $runIndex)[0].json;
return [
  {
    json: { ...item, run: item.file !== null && Object.keys($input.first().json).length === 0 },
    pairedItem: { item: 0 },
  },
];

function validateAudioMeta(raw, original, spec) {
  const extension = spec(raw?.mimeType, raw?.name),
    size = Number(raw?.size);
  if (
    raw?.id !== original.id ||
    raw.trashed !== false ||
    !raw.parents?.includes(original.folderId) ||
    raw.mimeType !== original.mime ||
    raw.capabilities?.canDownload !== true ||
    !extension ||
    !Number.isSafeInteger(size) ||
    size < 12 ||
    size > 4 * 1024 * 1024
  ) {
    throw Error(
      "The selected Drive file is no longer a downloadable audio recording of up to 4 MiB in the source folder.",
    );
  }
  const hash = raw.sha256Checksum ?? null;
  if (hash !== null && (typeof hash !== "string" || !/^[0-9a-f]{64}$/i.test(hash)))
    throw Error("Drive returned an invalid audio checksum.");
  return {
    ...original,
    size,
    sha256: hash?.toLowerCase() ?? null,
    extension,
    filename: "recording." + extension,
  };
}

